// aim.cpp
// Projects entity head positions to screen, returns smoothed crosshair delta
// within a 240px cone radius.
//
// Exported entry points:
//   bool AimInit(AimConfig cfg)          -- initialise with tuning parameters
//   AimDelta AimUpdate(const EntityList* entities, int count)
//                                        -- call each frame; returns pixel delta
//   void AimShutdown()                   -- release resources
//
// Build (standalone smoke test):
//   cl /std:c++17 /DAIM_SMOKE /W4 /EHsc aim.cpp /link user32.lib gdi32.lib

#pragma once
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <cmath>
#include <cstring>
#include <cstdint>
#include <limits>

// ---------------------------------------------------------------------------
// Public interface
// ---------------------------------------------------------------------------

struct AimConfig {
    float fovDegrees;      // horizontal FOV of the game camera
    float smoothFactor;    // 0 < smoothFactor <= 1  (1 = no smoothing)
    float conePx;          // cone radius in pixels (default 240)
    int   screenW;         // back-buffer / window width  in pixels
    int   screenH;         // back-buffer / window height in pixels
    float nearPlane;       // near-clip distance (world units)
    float farPlane;        // far-clip distance  (world units)
};

struct Vec3 {
    float x, y, z;
};

struct Matrix4x4 {
    float m[4][4]; // row-major; m[row][col]
};

struct EntityHead {
    Vec3  worldPos;   // head bone position in world space
    bool  visible;    // set by caller (e.g. via server-side visibility flag)
};

struct EntityList {
    EntityHead* heads;
    int         count;
};

struct AimDelta {
    float dx;      // horizontal pixel delta to apply to crosshair
    float dy;      // vertical   pixel delta to apply to crosshair
    bool  hasTarget;
};

// The game supplies the current view matrix each frame via this callback type.
// row-major: transforms world-space Vec3 → clip-space Vec4.
typedef bool (*ViewMatrixCallback)(Matrix4x4* out);

// ---------------------------------------------------------------------------
// Module state (file-scope, no heap)
// ---------------------------------------------------------------------------

static AimConfig      g_cfg;
static bool           g_initialised  = false;

// Smoothed delta accumulator (carry-over from previous frame)
static float          g_smoothDx     = 0.0f;
static float          g_smoothDy     = 0.0f;

// Optional view-matrix provider; caller may supply NULL to use identity.
static ViewMatrixCallback g_vmCb     = nullptr;

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

static inline float Vec3Dot(Vec3 a, Vec3 b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

// Multiply a world-space position by a 4×4 row-major matrix, return clip w.
// out_x, out_y are the NDC numerators (divide by w to get NDC).
static bool WorldToClip(const Matrix4x4& vp, Vec3 world,
                        float& out_x, float& out_y, float& out_w)
{
    out_x = vp.m[0][0] * world.x + vp.m[0][1] * world.y +
            vp.m[0][2] * world.z + vp.m[0][3];
    out_y = vp.m[1][0] * world.x + vp.m[1][1] * world.y +
            vp.m[1][2] * world.z + vp.m[1][3];
    out_w = vp.m[3][0] * world.x + vp.m[3][1] * world.y +
            vp.m[3][2] * world.z + vp.m[3][3];

    // Behind camera or outside near/far guard
    return (out_w > 0.0001f);
}

// Clip-space → pixel coords (top-left origin, matching most D3D conventions).
static void ClipToScreen(float cx, float cy, float cw,
                         int sw, int sh,
                         float& px, float& py)
{
    float ndcX =  cx / cw;
    float ndcY = -cy / cw;   // flip Y for screen space
    px = (ndcX + 1.0f) * 0.5f * static_cast<float>(sw);
    py = (ndcY + 1.0f) * 0.5f * static_cast<float>(sh);
}

// Build a simple perspective projection * identity view matrix when no
// callback is available, so the smoke test compiles without a live game.
static Matrix4x4 BuildFallbackVP(const AimConfig& c)
{
    Matrix4x4 m;
    memset(&m, 0, sizeof(m));
    float aspect = static_cast<float>(c.screenW) / static_cast<float>(c.screenH);
    float fovRad = c.fovDegrees * (3.14159265358979f / 180.0f);
    float f      = 1.0f / tanf(fovRad * 0.5f);
    float zn     = c.nearPlane;
    float zf     = c.farPlane;

    m.m[0][0] = f / aspect;
    m.m[1][1] = f;
    m.m[2][2] = zf / (zf - zn);
    m.m[2][3] = -(zn * zf) / (zf - zn);
    m.m[3][2] = 1.0f;   // row-major: w_clip = z_world
    return m;
}

// ---------------------------------------------------------------------------
// Public API implementation
// ---------------------------------------------------------------------------

bool AimInit(AimConfig cfg, ViewMatrixCallback vmCb /* = nullptr */)
{
    if (cfg.screenW <= 0 || cfg.screenH <= 0)       return false;
    if (cfg.smoothFactor <= 0.0f ||
        cfg.smoothFactor >  1.0f)                   return false;
    if (cfg.fovDegrees  <= 0.0f ||
        cfg.fovDegrees  >= 180.0f)                  return false;

    g_cfg          = cfg;
    g_vmCb         = vmCb;
    g_smoothDx     = 0.0f;
    g_smoothDy     = 0.0f;
    g_initialised  = true;
    return true;
}

// AimUpdate -------------------------------------------------------------------
// Projects every visible entity head, finds the one closest to screen-centre
// within the 240 px cone, computes raw pixel delta, and applies exponential
// smoothing before returning.
AimDelta AimUpdate(const EntityHead* heads, int count)
{
    AimDelta result{};
    result.hasTarget = false;

    if (!g_initialised || heads == nullptr || count <= 0)
        return result;

    // Acquire current view-projection matrix.
    Matrix4x4 vp;
    if (g_vmCb && g_vmCb(&vp)) {
        // matrix already filled
    } else {
        vp = BuildFallbackVP(g_cfg);
    }

    float cx   = static_cast<float>(g_cfg.screenW)  * 0.5f;
    float cy   = static_cast<float>(g_cfg.screenH)  * 0.5f;
    float cone = g_cfg.conePx > 0.0f ? g_cfg.conePx : 240.0f;
    float coneSq = cone * cone;

    float bestDistSq = std::numeric_limits<float>::max();
    float bestDx = 0.0f, bestDy = 0.0f;

    for (int i = 0; i < count; ++i) {
        const EntityHead& e = heads[i];
        if (!e.visible) continue;

        float clipX, clipY, clipW;
        if (!WorldToClip(vp, e.worldPos, clipX, clipY, clipW))
            continue;

        float px, py;
        ClipToScreen(clipX, clipY, clipW,
                     g_cfg.screenW, g_cfg.screenH,
                     px, py);

        float dx      = px - cx;
        float dy      = py - cy;
        float distSq  = dx * dx + dy * dy;

        // Reject targets outside the cone.
        if (distSq > coneSq) continue;

        if (distSq < bestDistSq) {
            bestDistSq = distSq;
            bestDx     = dx;
            bestDy     = dy;
            result.hasTarget = true;
        }
    }

    if (!result.hasTarget) {
        // Decay smoothed delta when no target is in cone.
        g_smoothDx *= (1.0f - g_cfg.smoothFactor);
        g_smoothDy *= (1.0f - g_cfg.smoothFactor);
        result.dx = 0.0f;
        result.dy = 0.0f;
        return result;
    }

    // Exponential moving average: new = prev + factor * (raw - prev)
    float sf   = g_cfg.smoothFactor;
    g_smoothDx = g_smoothDx + sf * (bestDx - g_smoothDx);
    g_smoothDy = g_smoothDy + sf * (bestDy - g_smoothDy);

    result.dx = g_smoothDx;
    result.dy = g_smoothDy;
    return result;
}

void AimShutdown()
{
    memset(&g_cfg, 0, sizeof(g_cfg));
    g_smoothDx    = 0.0f;
    g_smoothDy    = 0.0f;
    g_vmCb        = nullptr;
    g_initialised = false;
}

// ---------------------------------------------------------------------------
// Standalone smoke test  (cl /DAIM_SMOKE aim.cpp /link user32.lib gdi32.lib)
// ---------------------------------------------------------------------------
#ifdef AIM_SMOKE
#include <cstdio>

int main()
{
    AimConfig cfg{};
    cfg.fovDegrees  = 90.0f;
    cfg.smoothFactor= 0.25f;
    cfg.conePx      = 240.0f;
    cfg.screenW     = 1920;
    cfg.screenH     = 1080;
    cfg.nearPlane   = 0.1f;
    cfg.farPlane    = 10000.0f;

    bool ok = AimInit(cfg, nullptr);
    printf("AimInit: %s\n", ok ? "OK" : "FAIL");

    // One entity straight ahead, slightly right of centre.
    EntityHead heads[2]{};
    heads[0].worldPos = {2.0f, 0.0f, 50.0f};
    heads[0].visible  = true;
    heads[1].worldPos = {-999.0f, -999.0f, -1.0f}; // behind camera
    heads[1].visible  = true;

    for (int frame = 0; frame < 5; ++frame) {
        AimDelta d = AimUpdate(heads, 2);
        printf("Frame %d  hasTarget=%d  dx=%.3f  dy=%.3f\n",
               frame, (int)d.hasTarget, d.dx, d.dy);
    }

    AimShutdown();
    return 0;
}
#endif // AIM_SMOKE
